There is a bug in collapsed mode but I haven't figured out what is is yet. basically this test will fail and only reveal rows A & B regardless of whether you resolve C D etc...

```
    const A = createAsyncText('A');
    const B = createAsyncText('B');
    const C = createAsyncText('C');
    const D = createAsyncText('D');

    function Foo() {
      return (
        <div>
          <SuspenseList revealOrder="forwards" tail="collapsed">
            <Suspense fallback={<Text text="Loading A" />}>
              <A />
            </Suspense>
            <Suspense fallback={<Text text="Loading B" />}>
              <B />
            </Suspense>
            <Suspense fallback={<Text text="Loading C" />}>
              <C />
            </Suspense>
            <Suspense fallback={<Text text="Loading D" />}>
              <D />
            </Suspense>
          </SuspenseList>
        </div>
      );
    }
```

